{
  "name": "派能储能电池模组",
  "name_en": "Pylontech battery module",
  "manufacturer": "Pylontech",
  "description": "用于与派能储能锂电池模组或其电池管理系统通信，扫描总线上的电池模块，并读取协议版本、厂商信息、系统参数、管理信息、序列号及运行数值，适合实验室储能系统监测与集成。",
  "description_en": "Used to communicate with Pylontech energy storage battery modules or their battery management interface, scan battery modules on the bus, and read protocol version, manufacturer information, system parameters, management information, serial numbers, and operating values for laboratory energy storage monitoring and integration.",
  "actions": [
    {
      "action_name": "auto-get_frame_checksum",
      "description": "计算通信帧校验和。",
      "description_en": "Calculate the checksum of a communication frame."
    },
    {
      "action_name": "auto-get_info_length",
      "description": "获取信息区长度编码。",
      "description_en": "Get the encoded length of the information field."
    },
    {
      "action_name": "auto-send_cmd",
      "description": "向指定电池地址发送命令帧。",
      "description_en": "Send a command frame to the specified battery address."
    },
    {
      "action_name": "auto-read_frame",
      "description": "读取并解析设备返回的通信帧。",
      "description_en": "Read and parse a communication frame returned by the device."
    },
    {
      "action_name": "auto-scan_for_batteries",
      "description": "扫描总线上的电池模块并返回设备编号与序列号映射。",
      "description_en": "Scan battery modules on the bus and return a mapping of device IDs to serial numbers."
    },
    {
      "action_name": "auto-get_protocol_version",
      "description": "读取设备支持的通信协议版本。",
      "description_en": "Read the communication protocol version supported by the device."
    },
    {
      "action_name": "auto-get_manufacturer_info",
      "description": "读取设备厂商信息。",
      "description_en": "Read manufacturer information from the device."
    },
    {
      "action_name": "auto-get_system_parameters",
      "description": "读取系统参数。",
      "description_en": "Read system parameters."
    },
    {
      "action_name": "auto-get_management_info",
      "description": "读取指定电池模块的管理信息。",
      "description_en": "Read management information for the specified battery module."
    },
    {
      "action_name": "auto-get_module_serial_number",
      "description": "读取电池模块序列号。",
      "description_en": "Read the battery module serial number."
    },
    {
      "action_name": "auto-get_values",
      "description": "读取电池系统的运行数值。",
      "description_en": "Read operating values from the battery system."
    },
    {
      "action_name": "auto-get_values_single",
      "description": "读取指定电池模块的运行数值。",
      "description_en": "Read operating values from the specified battery module."
    }
  ],
  "tag_hints": [
    "Pylontech",
    "energy storage battery",
    "battery management",
    "battery telemetry",
    "module scanning",
    "serial communication"
  ]
}

